import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.BufferedReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStream input = System.in;
        BufferedReader br = new BufferedReader(new InputStreamReader(input));
        int n = Integer.parseInt(br.readLine());
        String line = br.readLine();
        String replaced = line.replaceAll("_+", " ");
        StringBuilder sb = new StringBuilder();
        for (char ch : replaced.toCharArray()) {
            if (ch == '(') {
                sb.append(" ( ");
            } else if (ch == ')') {
                sb.append(" ) ");
            } else {
                sb.append(ch);
            }
        }
        StringTokenizer tokenizer = new StringTokenizer(sb.toString());
        boolean inside = false;
        int maxLength = 0, parenthesesCount = 0;
        while (tokenizer.hasMoreTokens()) {
            String token = tokenizer.nextToken();
            if (token.contains("(")) {
                inside = true;
            } else if (token.contains(")")) {
                inside = false;
            } else if (!token.contains("(") && !token.contains(")")) {
                if (inside) {
                    parenthesesCount++;
                } else {
                    maxLength = Math.max(maxLength, token.length());
                }
            }
        }
        System.out.println(maxLength + " " + parenthesesCount);
    }
