#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cin.ignore(); // To consume the remaining newline after reading n
    string line;
    getline(cin, line);
    // Replace all sequences of underscores with a space
    string replaced;
    {
        string temp;
        for (size_t i = 0; i < line.size(); ++i) {
            if (line[i] == '_') {
                // Replace sequence of underscores with a single space
                while (i < line.size() && line[i] == '_') {
                    ++i;
                }
                replaced += ' ';
                --i; // adjust for the outer loop increment
            } else {
                replaced += line[i];
            }
        }
    }
    // Insert spaces around parentheses
    string sb;
    for (char ch : replaced) {
        if (ch == '(') {
            sb += " ( ";
        } else if (ch == ')') {
            sb += " ) ";
        } else {
            sb += ch;
        }
    }
    // Tokenize the string
    istringstream iss(sb);
    string token;
    bool inside = false;
    int maxLength = 0, parenthesesCount = 0;
    while (iss >> token) {
        if (token.find('(') != string::npos) {
            inside = true;
        } else if (token.find(')') != string::npos) {
            inside = false;
        } else if (token.find('(') == string::npos && token.find(')') == string::npos) {
            if (inside) {
                parenthesesCount++;
            } else {
                maxLength = max(maxLength, (int)token.length());
            }
        }
    }
    cout << maxLength << " " << parenthesesCount << "\n";
    return 0;
}
